function populatePersonOptions(select,selected=''){const current=selected?db.people.find(person=>person.id===selected)||(db.dismissedPeople||[]).find(person=>person.id===selected):null;const people=peopleForTurn(selectedTurn);if(current&&!people.some(person=>person.id===current.id))people.push(current);select.innerHTML=`<option value="">Selecione uma pessoa</option>${[...people].sort((a,b)=>a.name.localeCompare(b.name,'pt-BR',{sensitivity:'base'})).map(person=>`<option value="${esc(person.id)}" ${person.id===selected?'selected':''}>${esc(person.name)}</option>`).join('')}`}
function bindPersonNameSearch(inputId,listId,selectId,selectedId=''){const input=$('#'+inputId),picker=$('#'+selectId),list=$('#'+listId);const options=[...picker.options].filter(option=>option.value);const selected=options.find(option=>option.value===selectedId);input.value=selected?.textContent||'';input.setCustomValidity('');const showOptions=query=>{const normalized=normalizePeopleSearch(query||''),matches=options.filter(option=>normalizePeopleSearch(option.textContent).includes(normalized));list.innerHTML=matches.length?matches.map(option=>`<button type="button" class="person-search-option" role="option" data-value="${esc(option.value)}">${esc(option.textContent)}</button>`).join(''):'<div class="person-search-empty">Nenhuma pessoa encontrada.</div>';list.hidden=false};input.onfocus=()=>showOptions(input.value);input.onclick=()=>showOptions(input.value);input.oninput=()=>{const query=normalizePeopleSearch(input.value),match=options.find(option=>normalizePeopleSearch(option.textContent)===query);picker.value=match?.value||'';input.setCustomValidity(input.value.trim()&&!match?'Selecione um nome da lista.':'');if(picker.value)picker.dispatchEvent(new Event('change',{bubbles:true}));showOptions(input.value)};list.onclick=event=>{const option=event.target.closest('.person-search-option');if(!option)return;picker.value=option.dataset.value;input.value=options.find(item=>item.value===picker.value)?.textContent||'';input.setCustomValidity('');list.hidden=true;picker.dispatchEvent(new Event('change',{bubbles:true}))};input.onkeydown=event=>{if(event.key==='Escape')list.hidden=true};document.addEventListener('click',event=>{if(!event.target.closest('.person-search-control'))list.hidden=true})}
function vacationDayCount(start,end){if(!start||!end)return 0;const utc=value=>{const [y,m,d]=value.split('-').map(Number);return Date.UTC(y,m-1,d)};return Math.max(0,Math.round((utc(end)-utc(start))/86400000))}
function updateVacationDayCount(){const start=$('#vacationStart').value,end=$('#vacationEnd').value,summary=$('#vacationDayCount');if(end&&start&&end<start){summary.textContent='A data de retorno deve ser igual ou posterior à saída.';summary.setAttribute('aria-invalid','true');return}summary.removeAttribute('aria-invalid');const days=vacationDayCount(start,end);summary.innerHTML=`<strong class="vacation-days-number">${days}</strong> ${days===1?'dia':'dias'} de férias <span>(Fim é a data de retorno ao trabalho)</span>`}function openVacation(id=''){const item=(db.vacations||[]).find(row=>row.id===id);$('#vacationForm').reset();$('#vacationId').value=item?.id||'';populatePersonOptions($('#vacationPerson'),item?.personId||'');bindPersonNameSearch('vacationPersonSearch','vacationPersonNames','vacationPerson',item?.personId||'');$('#vacationTurn').innerHTML=db.turns.map(turn=>`<option value="${esc(turn)}" ${turn===(item?.turn||selectedTurn!=='all'&&selectedTurn||db.turns[0])?'selected':''}>${esc(displayTurn(turn))}</option>`).join('');$('#vacationStart').value=item?.start||`${reportPeriodKey()}-01`;$('#vacationEnd').value=item?.end||`${reportPeriodKey()}-01`;$('#vacationDialogTitle').textContent=item?'Editar férias':'Programar férias';updateVacationDayCount();$('#vacationDialog').showModal()}
function openIncident(id=''){const item=(db.incidents||[]).find(row=>row.id===id);$('#incidentForm').reset();$('#incidentId').value=item?.id||'';$('#incidentDate').value=item?.date||`${reportPeriodKey()}-${String(new Date().getDate()).padStart(2,'0')}`;populatePersonOptions($('#incidentPerson'),item?.personId||'');bindPersonNameSearch('incidentPersonSearch','incidentPersonNames','incidentPerson',item?.personId||'');$('#incidentDescription').value=item?.description||'';$('#incidentDialogTitle').textContent=item?'Editar ocorrência':'Nova ocorrência';$('#incidentDialog').showModal()}
document.addEventListener('click',async e=>{if(e.target.closest('#toggleAllVacations')){showAllVacations=!showAllVacations;render();return}if(e.target.closest('#importVacationBtn'))$('#vacationExcelFile')?.click();const vacationChartButton=e.target.closest('[data-vacation-chart]');if(vacationChartButton){vacationChartMode=vacationChartButton.dataset.vacationChart;render();return}if(e.target.closest('#addVacation'))openVacation();if(e.target.closest('#addIncident'))openIncident();const editVacation=e.target.closest('.edit-vacation');if(editVacation)openVacation(editVacation.dataset.id);const editIncident=e.target.closest('.edit-incident');if(editIncident)openIncident(editIncident.dataset.id);const deleteVacation=e.target.closest('.delete-vacation');if(deleteVacation){const item=db.vacations.find(row=>row.id===deleteVacation.dataset.id);if(item&&await confirmDelete(`Excluir as férias de ${reportPersonName(item)}?`)){db.vacations=db.vacations.filter(row=>row.id!==item.id);save();render()}}const deleteIncident=e.target.closest('.delete-incident');if(deleteIncident){const item=db.incidents.find(row=>row.id===deleteIncident.dataset.id);if(item&&await confirmDelete(`Excluir a ocorrência de ${reportPersonName(item)}?`)){db.incidents=db.incidents.filter(row=>row.id!==item.id);save();render()}}});
